-- Starting-zone creature loot from archived Jabbithole drop tables. Generated by wildstar-archive/tools/build_loot.py.
-- probability = observed percentage of kills that dropped the item. Loot group ids 1000000+.
DELETE FROM `entity_loot` WHERE `lootGroupId` >= 1000000;
DELETE FROM `loot_item` WHERE `id` >= 1000000;
DELETE FROM `loot_group` WHERE `id` >= 1000000;
